<?php
namespace App\Services;
use App\Models\{SitePresentation,School};
use Illuminate\Support\Facades\{Schema,Storage};
use Illuminate\Validation\ValidationException;
final class SitePresentationService {
 public function settings():?SitePresentation{return Schema::hasTable('site_presentations')?SitePresentation::find(1):null;}
 public function loginPhoto():array{$s=$this->settings();$valid=$s?->login_photo_path&&Storage::disk('local')->exists($s->login_photo_path);return ['url'=>$valid?route('site.login-photo',['v'=>basename($s->login_photo_path,'.webp')]):asset('images/siswa-berangkat-ke-sekolah.webp'),'alt'=>$s?->login_photo_alt??'Ilustrasi perjalanan ke sekolah'];}
 public function registerPhoto():array{$s=$this->settings();$valid=$s?->register_photo_path&&Storage::disk('local')->exists($s->register_photo_path);return ['url'=>$valid?route('site.register-photo',['v'=>basename($s->register_photo_path,'.webp')]):asset('images/siswa-berangkat-ke-sekolah.webp'),'alt'=>$s?->register_photo_alt??'Ilustrasi perjalanan ke sekolah'];}
 public function contact(?School $school=null):?string{return $school?->settings['help_contact']??(config('account.school_contacts')[$school?->npsn??'']??config('account.school_contacts')[(string)$school?->id]??$this->settings()?->help_contact??config('account.help_contact'));}
 public function validateContact(?string $value):?string{$value=trim($value??'');if($value==='')return null;if(preg_match('/[<>\r\n]/',$value)||strlen($value)>300)throw ValidationException::withMessages(['help_contact'=>'Gunakan satu kontak resmi, maksimal 300 karakter tanpa markup.']);if(preg_match('/^[a-z][a-z0-9+.-]*:/i',$value)&&!preg_match('/^(https:\/\/|mailto:)/i',$value))throw ValidationException::withMessages(['help_contact'=>'Tautan hanya boleh HTTPS atau mailto. Nomor telepon dapat ditulis sebagai teks.']);if(str_starts_with(strtolower($value),'https://')&&!filter_var($value,FILTER_VALIDATE_URL))throw ValidationException::withMessages(['help_contact'=>'Tautan HTTPS tidak valid.']);if(str_starts_with(strtolower($value),'mailto:')&&!filter_var(substr($value,7),FILTER_VALIDATE_EMAIL))throw ValidationException::withMessages(['help_contact'=>'Isi mailto dengan alamat email resmi, tanpa parameter tambahan.']);return $value;}
 public function photo(){ $s=$this->settings();$path=$s?->login_photo_path;abort_unless(is_string($path)&&preg_match('#^site-photos/[a-f0-9-]{36}\.webp$#',$path)&&Storage::disk('local')->exists($path),404);return response(Storage::disk('local')->get($path))->header('Content-Type','image/webp')->header('Cache-Control','no-store, private')->header('X-Content-Type-Options','nosniff');}
 public function registerPhotoFile(){ $s=$this->settings();$path=$s?->register_photo_path;abort_unless(is_string($path)&&preg_match('#^site-photos/[a-f0-9-]{36}\.webp$#',$path)&&Storage::disk('local')->exists($path),404);return response(Storage::disk('local')->get($path))->header('Content-Type','image/webp')->header('Cache-Control','no-store, private')->header('X-Content-Type-Options','nosniff');}
}
